export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity,m=inputs.mass;
const T=2*u/g,ta=u/g;
const t=Math.min(Math.max(time,0),T);
const v=u-g*t,y=u*t-g*t*t/2,F=m*g;
const H=u*u/(2*g);
let s;
if(time<=0)s='Ready to toss';else if(Math.abs(t-ta)<0.005)s='At the top';else if(t<ta)s='Rising';else if(t<T-1e-9)s='Falling';else s='Back at launch height';
const o=[];
o.push(...sdk.panel({id:'lane.motion',x:10,y:32,w:300,h:376,title:'The motion',state:s}));
o.push(sdk.axis('axis.h',{x:70,y:380,length:300,orientation:'y',min:0,max:2.2,ticks:[0,1,2],label:'Height',unit:'m'}));
const py=380-y/2.2*300;
o.push(sdk.circle('ball.toss',150,py,24,{}));
o.push(...sdk.vector('vec.v',{x:150,y:py},{value:v,direction:'up'},{scale:12,label:'v',role:'input'}));
o.push(...sdk.vector('vec.a',{x:185,y:py},{value:-g,direction:'up'},{scale:5,label:'a',role:'warning'}));
o.push(...sdk.callout(215,100,['v = '+sdk.format(v,2)+' m/s','a = '+sdk.format(-g,2)+' m/s²','Fg = '+sdk.format(F,2)+' N'],{id:'callout.toss'}));
const pts=[],cont=[];
for(let i=0;i<=12;i++){const tt=Math.min(t,T)*i/12;pts.push({x:tt,y:u-g*tt});}
if(pts.length<2)pts.push(pts[0]);
o.push(sdk.plot('plot.vt',{x:330,y:40,w:300,h:330,axes:{x:{label:'t',min:0,max:1.8,unit:'s'},y:{label:'v',min:-5.5,max:5.5,unit:'m/s'}},series:[{label:'v = u - g t',kind:'line',points:pts}]}));
o.push(sdk.text('plot.vt.note',480,395,'slope a = -g = '+sdk.format(-g,1)+' m/s²',{align:'middle'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:F},{id:'motionState',value:s}]},quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:H,height:y,velocity:v,acceleration:-g,force:F}};}
